public ExcuteResult TransferDispenseToBond(bool isManual = false)
        {
            try
            {
                // 如果Bond基板不是空闲状态
                if (this.TransportProgram.BondSubSectionProgram.SubSectionState !=
                    SubSectionStateEnum.NoMaterial ||
                    this.TransportProgram.DispenseSubSectionProgram.SubSectionState !=
                    SubSectionStateEnum.HasMaterial)
                {
                    // 如果不满足条件
                    return ExcuteResult.NoStart;
                }

                TransportProvider.RecordTime("流道调试", "检测到Bond有料");

                // 如果不是手动调试模式
                if (isManual == false)
                {
                    // 等点胶线程给信号
                    bool rt = SignalPool.GetInstance().AllowDispenseTransferToBondSignal.Wait();
                    if (rt == false)
                    {
                        // 如果点了停止 则退出
                        return ExcuteResult.Abort;
                    }
                }
                else
                {
                    if (ProductConfiguration.GetInstance().TransportUnitConfig.SubstrateProcessing == TransportUnitSystem.Model.SubstrateProcessingEnum.Divide)
                    {
                        if (this.TransportProgram.DispenseSubSectionProgram.IsTuInDispense1)
                        {
                            return ExcuteResult.NoStart;
                        }
                    }
                }

            retry:
                TransportProvider.RecordTime("流道调试", "点胶流道收到信号可以传送到Bond");
                this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
                        SubSectionStateTransferEnum.Transfering;

                List<Task> tasks = new List<Task>();

                if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
                {
                    tasks.Add(
                        Task.Run(
                            () =>
                                {
                                    // 轨道顶升气缸顶起
                                    this.DispenseSubSectionController.UnClamp();
                                }));
                }

                tasks.Add(Task.Run(
                    () =>
                        {
                            // 轨道顶升气缸顶起
                            this.BondSubSectionController.UnClamp();
                        }));


                tasks.Add(Task.Run(
                    () =>
                        {
                            // 点胶挡料气缸降下
                            this.DispenseSubSectionController.BlockCylinder1DownAndDelay(10);
                        }));

                tasks.Add(Task.Run(
                    () =>
                        {
                            // 点胶挡料气缸降下
                            this.DispenseSubSectionController.BlockCylinder2DownAndDelay(10);
                        }));

                tasks.Add(Task.Run(
                    () =>
                        {
                            // Bond 挡料气缸升起
                            this.BondSubSectionController.BlockCylinderUpAndDelay(10);
                        }));


                // 等待所有任务完成
                Task.WaitAll(tasks.ToArray());

                TransportProvider.RecordTime("流道调试", "所有气缸动作完成，点胶皮带开始传动");

                // 皮带转动
                this.DispenseSubSectionController.MoveBeltNoWaitArrive();

                Thread.Sleep(200);

                // 入料口是否有料
                bool hasMaterialInOutlet = false;
                while (this.DispenseSubSectionController.IsMoving())
                {
                    // 出料料检测（传感器D）
                    hasMaterialInOutlet =
                        this.DispenseSubSectionController.HasMaterialInOutlet();

                    // 如果 D 感应到了 则跳出循环
                    if (hasMaterialInOutlet)
                    {
                        break;
                    }

                    Thread.Sleep(300);
                }

                // 皮带转完了 出料传感器 D还没有感应到料， 则报警
                if (hasMaterialInOutlet == false)
                {
                    this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
                        SubSectionStateTransferEnum.Alarm;

                    // 如果感应到，则报警：上料台入料卡料
                    DialogResult dr = AKRSMessageBoxExt.Show(
                        @"点胶载台卡料
                          点击
                         重试: 重新上料
                         终止：停止工作
                         忽略: 忽略此报警",
                        $"报警",
                        new[] { "重试", "终止", "忽略" },
                        new[] { DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore });

                    switch (dr)
                    {
                        case DialogResult.Retry:
                            goto retry;

                        case DialogResult.Abort:
                            // 停止
                            return ExcuteResult.Abort;

                        case DialogResult.Ignore:
                            // 停止
                            break;
                    }
                }
                else
                {
                    this.TransportProgram.BondSubSectionProgram.SubSectionTransferState =
                        SubSectionStateTransferEnum.Transfering;

                    // bond 皮带转动  并等待转完
                    this.BondSubSectionController.MoveBeltWaitArrive();

                    hasMaterialInOutlet =
                        this.DispenseSubSectionController.HasMaterialInOutlet();

                    // 如果 D 感应到了 报警
                    if (hasMaterialInOutlet)
                    {
                        this.TransportProgram.BondSubSectionProgram.SubSectionTransferState =
                            SubSectionStateTransferEnum.Alarm;

                        // 如果B 感应到，则报警：上料台入料卡料
                        DialogResult dr = AKRSMessageBoxExt.Show(
                            @"Bond载台卡料
                          点击
                         重试: 重新上料
                         终止：停止工作
                         忽略: 忽略此报警",
                            $"报警",
                            new[] { "重试", "终止", "忽略" },
                            new[] { DialogResult.Retry, DialogResult.Abort, DialogResult.Ignore });

                        switch (dr)
                        {
                            case DialogResult.Retry:
                                goto retry;

                            case DialogResult.Abort:
                                // 停止
                                return ExcuteResult.Abort;

                            case DialogResult.Ignore:
                                break;
                        }
                    }
                }

                tasks.Clear();

                tasks.Add(Task.Run(
                    () =>
                        {
                            // 轨道顶升气缸降下
                            // this.TransportModule.DispenseSubSectionModule.TrackLiftCylinderUp(50);
                            this.BondSubSectionController.Clamp();
                        }));

                tasks.Add(Task.Run(
                    () =>
                        {
                            this.DispenseSubSectionController.BlockCylinder1UpAndDelay(10);
                        }));

                tasks.Add(Task.Run(
                    () =>
                        {
                            this.DispenseSubSectionController.BlockCylinder2UpAndDelay(10);
                        }));

                // 等待所有任务完成
                Task.WaitAll(tasks.ToArray());

                this.TransportProgram.BondSubSectionProgram.TransportUnit =
                    this.TransportProgram.DispenseSubSectionProgram.TransportUnit;

                if (this.TransportProgram.BondSubSectionProgram.TransportUnit == null && isManual)
                {
                    this.TransportProgram.BondSubSectionProgram.TransportUnit = new TransportUnit(CurrentMachineSystemEnum.System2);
                }

                this.TransportProgram.BondSubSectionProgram.TransportUnit.Refresh();

                this.TransportProgram.DispenseSubSectionProgram.TransportUnit = null;

                // 状态改成有料
                this.TransportProgram.BondSubSectionProgram.SubSectionState =
                    SubSectionStateEnum.HasMaterial;

                this.TransportProgram.DispenseSubSectionProgram.TransportUnit = null;
                this.TransportProgram.DispenseSubSectionProgram.SubSectionState =
                    SubSectionStateEnum.NoMaterial;

                this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
                SubSectionStateTransferEnum.Ready;
                this.TransportProgram.BondSubSectionProgram.SubSectionTransferState =
                SubSectionStateTransferEnum.Ready;

                this.TransportProgram.Save();
                return ExcuteResult.Success;
            }
            catch (Exception ex)
            {
                LogHelper.Post(
                    Level.Error,
                    $"产品传入Bond载台出现异常",
                    ex,
                    LogCategory.Transport);

                AKRSXtraMessageBox.Show(
                    $@"产品传入Bond载台出现异常: \r\n
                                          Exception message:{ex.Message} \r\n
                                          StackTrace: {ex.StackTrace}",
                    "Exception",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Error);

                return ExcuteResult.Exception;
            }
        }

public void UnClamp()
        {
            // 如果流道或者系统1没有配置，直接返回
            if ((!MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
                || (!MachineHardwareConfiguration.GetInstance().IsTransportConfigured)) 
            {
                return;
            }

            if (this.dispenseSubSectionProgram.TransportBeltSetting == null)
            {
                DialogResult dialog = AKRSMessageBoxExt.Show(
                    $"传输系统皮带设置为空，松开夹爪失败!  \r\n请先设置传输皮带参数！",
                    "报警",
                    new string[] { "确认" },
                    new DialogResult[] { DialogResult.OK });

                return;
            }

        RetryCommand:
            switch (this.dispenseSubSectionProgram.TransportBeltSetting.UnClampMode)
            {
                case UnClampModeEnum.Rising:
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.BeforeUnClampingDelay);
                    this.dispenseSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(false);
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.AfterUnClampingDelay);
                    break;

                case UnClampModeEnum.Vacuum:
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.BeforeUnClampingDelay);
                    this.dispenseSubSectionModule.SubstrateVaccumElectric.SetOutputValue(false);

                    if (this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric != null)
                    {
                        this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric.SetOutputValue(false);
                    }

                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.AfterUnClampingDelay);
                    break;

                case UnClampModeEnum.RisingAndVacuum:
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.BeforeUnClampingDelay);
                    this.dispenseSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(false);

                    if (this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric != null)
                    {
                        this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric.SetOutputValue(false);
                    }

                    this.dispenseSubSectionModule.SubstrateVaccumElectric.SetOutputValue(false);
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.AfterUnClampingDelay);
                    break;

                case UnClampModeEnum.VacuumAndRising:
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.BeforeUnClampingDelay);
                    this.dispenseSubSectionModule.SubstrateVaccumElectric.SetOutputValue(false);

                    if (this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric != null)
                    {
                        this.dispenseSubSectionModule.SubstrateAdditionVaccumElectric.SetOutputValue(false);
                    }

                    this.dispenseSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(false);
                    Thread.Sleep(this.dispenseSubSectionProgram.BondinsertSetting.AfterUnClampingDelay);
                    break;
            }

            Thread.Sleep(500);

            bool ret1 = this.dispenseSubSectionModule.TrackFrontCylinder1NLSensor.GetInputValue();
            bool ret2 = this.dispenseSubSectionModule.TrackFrontCylinder2NLSensor == null || this.dispenseSubSectionModule.TrackFrontCylinder2NLSensor.GetInputValue();
            bool ret3 = this.dispenseSubSectionModule.TrackBackCylinder1NLSensor == null || this.dispenseSubSectionModule.TrackBackCylinder1NLSensor.GetInputValue();

            if ((ret1 && ret2 && ret3) == false)
            {
                DialogResult dialog = AKRSMessageBoxExt.Show(
                    $"点胶工作台气缸松开失败，请检查传感器状态！ \r\n",
                "Alarm",
                    new string[] { "重试", "忽略", "终止" },
                    new DialogResult[] { DialogResult.Retry, DialogResult.Ignore, DialogResult.Abort, });

                switch (dialog)
                {
                    case DialogResult.Retry:
                        goto RetryCommand;

                    // 终止
                    case DialogResult.Abort:
                        Machine.GetInstance().Stop();
                        return;

                    // 忽略
                    case DialogResult.Ignore:
                        break;
                }
            }
        }

public void BlockCylinder1DownAndDelay(int afterDelay)
        {
            // 如果流道或者系统1没有配置，直接返回
            if ((!MachineHardwareConfiguration.GetInstance().IsSystem1Configrated) || (!MachineHardwareConfiguration.GetInstance().IsTransportConfigured))
            {
                return;
            }

            this.dispenseSubSectionModule.BlockCylinder1Down();
            Thread.Sleep(afterDelay);
        }

public void BlockCylinder2DownAndDelay(int afterDelay)
        {
            // 如果流道或者系统1没有配置，直接返回
            if ((!MachineHardwareConfiguration.GetInstance().IsSystem1Configrated) || (!MachineHardwareConfiguration.GetInstance().IsTransportConfigured))
            {
                return;
            }

            this.dispenseSubSectionModule.BlockCylinder2Down();
            Thread.Sleep(afterDelay);
        }

public override void MoveBeltNoWaitArrive()
        {
            // 按时间传送， 时间配置在参数里
            TransportBeltSetting transportBeltSetting = this.dispenseSubSectionProgram.TransportBeltSetting;

            if (transportBeltSetting == null)
            {
                throw new Exception("dispense transport belt setting is not exist");
            }

            double transportDistance = transportBeltSetting.ForwardTransportDistance;

            // 皮带1相对运动指令
            this.dispenseSubSectionModule.SendRelativeMoveCommandBelt(transportDistance, transportBeltSetting.ForwardVelRate);
        }

public void Clamp()
        {
            if (MachineHardwareConfiguration.GetInstance().IsTransportConfigured)
            {
                if (this.bondSubSectionProgram.TransportBeltSetting == null)
                {
                    DialogResult dialog = AKRSMessageBoxExt.Show(
                        $"传输系统皮带设置为空，夹紧夹爪失败!  \r\n请先设置传输皮带参数！",
                        "报警",
                        new string[] { "确认" },
                        new DialogResult[] { DialogResult.OK });

                    return;
                }

            RetryCommand:
                switch (this.bondSubSectionProgram.TransportBeltSetting.ClampMode)
                {
                    case ClampModeEnum.Lowering:
                        Thread.Sleep(this.bondSubSectionProgram.BondinsertSetting.BeforeClampingDelay);
                        this.bondSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(true);
                        Thread.Sleep(this.bondSubSectionProgram.BondinsertSetting.AfterClampingDelay);
                        break;

                    case ClampModeEnum.Vacuum:
                        Thread.Sleep(this.bondSubSectionProgram.BondinsertSetting.BeforeClampingDelay);
                        this.bondSubSectionModule.SubstrateVaccumElectric.SetOutputValue(true);
                        Thread.Sleep(this.bondSubSectionProgram.BondinsertSetting.AfterClampingDelay);
                        break;

                    case ClampModeEnum.LoweringAndVacuum:
                        Thread.Sleep(this.bondSubSectionProgram.BondinsertSetting.BeforeClampingDelay);
                        this.bondSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(true);
                        this.bondSubSectionModule.SubstrateVaccumElectric.SetOutputValue(true);
                        Thread.Sleep(this.bondSubSectionProgram.BondinsertSetting.AfterClampingDelay);
                        break;

                    case ClampModeEnum.VacuumAndLowering:
                        Thread.Sleep(this.bondSubSectionProgram.BondinsertSetting.BeforeClampingDelay);
                        this.bondSubSectionModule.SubstrateVaccumElectric.SetOutputValue(true);
                        this.bondSubSectionModule.TrackLiftCylinderElectric.SetOutputValue(true);
                        Thread.Sleep(this.bondSubSectionProgram.BondinsertSetting.AfterClampingDelay);
                        break;
                }

                Thread.Sleep(500);
                bool ret1 = this.bondSubSectionModule.TrackFrontCylinder1PLSensor.GetInputValue();
                bool ret2 = this.bondSubSectionModule.TrackFrontCylinder2PLSensor == null
                            || this.bondSubSectionModule.TrackFrontCylinder2PLSensor.GetInputValue();
                bool ret3 = this.bondSubSectionModule.TrackBackCylinder1PLSensor == null
                            || this.bondSubSectionModule.TrackBackCylinder1PLSensor.GetInputValue();

                if ((ret1 && ret2 && ret3) == false)
                {
                    DialogResult dialog = AKRSMessageBoxExt.Show(
                        $"固晶工作台夹紧夹爪失败，请检查传感器状态!  \r\n"
                        + "重试：重新松开夹爪\r\n"
                        + "忽略：忽略这个报警\r\n"
                        + "退出：退出 \r\n",
                        "报警",
                        new string[] { "重试", "忽略", "退出" },
                        new DialogResult[] { DialogResult.Retry, DialogResult.Ignore, DialogResult.Abort, });
                    switch (dialog)
                    {
                        case DialogResult.Retry:
                            goto RetryCommand;

                        // 终止
                        case DialogResult.Abort:
                            Machine.GetInstance().Stop();
                            return;

                        // 忽略
                        case DialogResult.Ignore:
                            break;
                    }
                }
            }
            else
            {
                this.OpenVacuum();
            }
        }

public void BlockCylinderUpAndDelay(int afterDelay)
        {
            this.bondSubSectionModule.BlockCylinderUp();
            Thread.Sleep(afterDelay);

            // Todo 判断限位
        }

public override void MoveBeltWaitArrive()
        {
            // 按时距离送
            TransportBeltSetting transportBeltSetting = this.bondSubSectionProgram.TransportBeltSetting;

            if (transportBeltSetting == null)
            {
                throw new Exception("固晶工作台没有设置传输距离数据集");
            }

            double transportDistance = transportBeltSetting.ForwardTransportDistance;

            // 皮带1相对运动指令
            this.bondSubSectionModule.RelativeMoveBelt(transportDistance, transportBeltSetting.ForwardVelRate);
        }

public virtual void RelativeMoveBelt(double transportDistance, double velRate)
        {
            this.BeltAxisX.RelativeMove(transportDistance, this.BeltAxisX.AxisMovePara.AbsoluteMoveSpeed * velRate);
        }

public enum ClampModeEnum
    {
        /// <summary>
        /// 仅真空
        /// </summary>
        [Description("真空")]
        Vacuum,

        /// <summary>
        /// 仅降低轨道
        /// </summary>
        [Description("降低轨道")]
        Lowering,

        /// <summary>
        /// 真空后降低轨道
        /// </summary>
        [Description("真空后降低轨道")]
        VacuumAndLowering,

        /// <summary>
        /// 降低轨道后真空
        /// </summary>
        [Description("降低轨道后真空")]
        LoweringAndVacuum
    }

public void Start()
        {
            #region 送板机到入料段(联机)

            // 联机
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online
                || MachineHardwareConfiguration.GetInstance().LoadConfiguration
                == LoadConfigurationEnum.OnlineWithAutoLoader)
            {
                if (this.transferAutoLoaderToLoadingBeltTask == null
                    || this.transferAutoLoaderToLoadingBeltTask.Status != TaskStatus.Running)
                {
                    this.transferAutoLoaderToLoadingBeltTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("送板机传入料段线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 如果在单片上料模式下，没有准备好的料片，就继续等待
                                if (!TransportProvider.PrepareFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                ExcuteResult ret = this.transportController.TransferAutoLoaderToLoading();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(500);
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;

                                        break;
                                }

                                Thread.Sleep(500);
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"送板机传入料段线程：{ex.Message}");
                        }
                    });
                    this.transferAutoLoaderToLoadingBeltTask.ConfigureAwait(false);
                }
            }

            #endregion

            #region 入料段到点胶

            // 未配置自动上下料
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.None)
            {
                if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                           == SubSectionStateEnum.HasMaterial)
                {
                    DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                        @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                        $"Warning",
                        new[] { "Yes", "No" },
                        new[] { DialogResult.Yes, DialogResult.No });

                    switch (dr)
                    {
                        case DialogResult.Yes:
                            SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                            break;

                        case DialogResult.No:
                            Machine.GetInstance().Stop();
                            break;
                    }
                }
            }
            else if (MachineHardwareConfiguration.GetInstance().LoadConfiguration != LoadConfigurationEnum.LoaderBin)
            {
                // 皮带上料
                // 防止线程多次启动
                if (this.transferLoadBeltToDispense1Task == null || this.transferLoadBeltToDispense1Task.Status != TaskStatus.Running)
                {
                    this.transferLoadBeltToDispense1Task = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("入料皮带传入点胶1线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                    }
                                }

                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                            @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                            $"Warning",
                                            new[] { "Yes", "No" },
                                            new[] { DialogResult.Yes, DialogResult.No });

                                        switch (dr)
                                        {
                                            case DialogResult.Yes:
                                                SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                                break;

                                            case DialogResult.No:
                                                Machine.GetInstance().Stop();
                                                break;
                                        }
                                    }

                                    continue;
                                }

                                // 如果在连续上料模式下，客户点击了不在上料，就继续等待
                                if (!TransportProvider.ContinuousFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                ExcuteResult ret = this.transportController.TransferLoadBeltToDispense();

                                // 如果有料 直接发信号
                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:
                                        // 传送到点胶1结束
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;
                                        break;
                                }

                                if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated == false)
                                {
                                    SignalPool.GetInstance().AllowDispenseTransferToBondSignal.Set();
                                }

                                Thread.Sleep(100);
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"入料传入点胶1线程异常：{ex.Message}");
                        }
                    });

                    this.transferLoadBeltToDispense1Task.ConfigureAwait(false);
                }
            }
            else
            {
                // 配置自动上下料
                // 防止线程多次启动
                if (this.transferLoaderBinToDispense1Task == null || this.transferLoaderBinToDispense1Task.Status != TaskStatus.Running)
                {
                    this.transferLoaderBinToDispense1Task = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("上料仓传入点胶1线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                // 第一次启动时，如果dispense table上有料 则直接开始干
                                if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                    }
                                }

                                if (firstStart)
                                {
                                    firstStart = false;
                                    if (TransportProgram.GetInstance().DispenseSubSectionProgram.SubSectionState
                                        == SubSectionStateEnum.HasMaterial)
                                    {
                                        DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                            @" 检测到点胶载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                            $"Warning",
                                            new[] { "Yes", "No" },
                                            new[] { DialogResult.Yes, DialogResult.No });

                                        switch (dr)
                                        {
                                            case DialogResult.Yes:
                                                SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();
                                                break;

                                            case DialogResult.No:
                                                Machine.GetInstance().Stop();
                                                break;
                                        }
                                    }

                                    continue;
                                }

                                // 点击不再上料就一直等待
                                if (!TransportProvider.ContinuousFeeding)
                                {
                                    Thread.Sleep(1000);
                                    continue;
                                }

                                // 等允许推料信号
                                if (!SignalPool.GetInstance().LoaderAllowPushSignal.Wait())
                                {
                                    return;
                                }

                                // 推料到点胶
                                ExcuteResult ret = this.transportController.TransferLoadBinToDispense();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(500);
                                        continue;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        return;

                                    case ExcuteResult.Success:

                                        // 传料完成
                                        SignalPool.GetInstance().TransferToDispense1FinishedSignal.Set();

                                        // 传送成功，在单片上料模式下清除准备好的料片
                                        TransportProvider.PrepareFeeding = false;
                                        break;

                                    case ExcuteResult.Exception:
                                        Machine.GetInstance().Stop();
                                        return;

                                    // 下一片
                                    case ExcuteResult.None:
                                        break;
                                }

                                // 手动复位
                                SignalPool.GetInstance().LoaderAllowPushSignal.ReSet();

                                // 允许料仓移动
                                SignalPool.GetInstance().AllowLoaderMoveSignal.Set();
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"入料仓传入点胶1线程异常：{ex.Message}");
                        }
                    });

                    this.transferLoaderBinToDispense1Task.ConfigureAwait(false);
                }
            }

            #endregion

            #region 点胶1 传到 点胶2
            if (this.transferDispense1ToDispense2Task == null || this.transferDispense1ToDispense2Task.Status != TaskStatus.Running)
            {
                // 本次节点先不用， 下一迭代 加上
                this.transferDispense1ToDispense2Task = Task.Run(() =>
                {
                    CommonUtil.SetCurrentThreadName("点胶1传入点胶2线程");

                    try
                    {
                        while (Signal.WaitStart())
                        {
                            ExcuteResult ret = this.transportController.TransferDispense1ToDispense2();

                            switch (ret)
                            {
                                case ExcuteResult.NoStart:
                                    Thread.Sleep(500);
                                    break;

                                case ExcuteResult.Abort:
                                    Machine.GetInstance().Stop();
                                    break;

                                case ExcuteResult.Success:
                                    // 给Bond 域发信号, Bond轨道传送完成
                                    SignalPool.GetInstance().TransferToDispense2FinishedSignal.Set();
                                    break;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        AKRSXtraMessageBox.Show($"点胶1传入点胶2线程：{ex.Message}");
                    }
                });
                this.transferDispense1ToDispense2Task.ConfigureAwait(false);
            }
            #endregion

            if (this.transferDispenseToBondTask == null || this.transferDispenseToBondTask.Status != TaskStatus.Running)
            {
                this.transferDispenseToBondTask = Task.Run(() =>
                {
                    CommonUtil.SetCurrentThreadName("点胶传入Bond线程");

                    bool firstStart = true;
                    try
                    {
                        // 正在工作
                        while (Signal.WaitStart())
                        {
                            // 第一次启动时，如果dispense table上有料 则直接开始干
                            if (!TransportDevicePara.GetInstance().IsReStartWarn && firstStart)
                            {
                                firstStart = false;
                                if (TransportProgram.GetInstance().BondSubSectionProgram.SubSectionState
                                    == SubSectionStateEnum.HasMaterial)
                                {
                                    SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                }
                            }

                            // 第一次启动时，如果Bond table上有料 则直接开始干
                            if (firstStart)
                            {
                                firstStart = false;
                                if (TransportProgram.GetInstance().BondSubSectionProgram.SubSectionState
                                    == SubSectionStateEnum.HasMaterial)
                                {
                                    DialogResult dr = AKRSMessageBoxExt.ShowWarn(
                                        @" 检测到Bond载台上有料，是否继续工作?
                                        Click
                                        Yes: 继续做料
                                        No: 停止工作",
                                        $"Warning",
                                        new[] { "Yes", "No" },
                                        new[] { DialogResult.Yes, DialogResult.No });

                                    switch (dr)
                                    {
                                        case DialogResult.Yes:
                                            SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                            break;

                                        case DialogResult.No:
                                            Machine.GetInstance().Stop();
                                            break;
                                    }
                                }

                                continue;
                            }


                            ExcuteResult ret = this.transportController.TransferDispenseToBond();

                            switch (ret)
                            {
                                case ExcuteResult.NoStart:
                                    // 提速先注释掉
                                    //Thread.Sleep(50);
                                    break;

                                case ExcuteResult.Abort:
                                    Machine.GetInstance().Stop();
                                    break;

                                case ExcuteResult.Success:
                                    // 给Bond 域发信号, Bond轨道传送完成
                                    SignalPool.GetInstance().TransferToBondFinishedSignal.Set();
                                    break;
                            }

                            Thread.Sleep(50);
                        }
                    }
                    catch (Exception ex)
                    {
                        AKRSXtraMessageBox.Show($"点胶传入Bond线程：{ex.Message}");
                    }
                });
                this.transferDispenseToBondTask.ConfigureAwait(false);
            }

            if (this.transferBondToWaitingUnloadTask == null || this.transferBondToWaitingUnloadTask.Status != TaskStatus.Running)
            {
                this.transferBondToWaitingUnloadTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("Bond传入等待区线程");

                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                ExcuteResult ret = this.transportController.TransferBondToWaitingUnload();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:

                                        break;

                                    case ExcuteResult.Abort:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Abort");

                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Success");
                                        break;

                                    case ExcuteResult.Exception:
                                        TransportProvider.RecordTime("Bond传入等待区线程", "返回Exception");
                                        Machine.GetInstance().Stop();
                                        break;
                                }

                                Thread.Sleep(100);
                            }
                        }
                        catch (Exception ex)
                        {
                            TransportProvider.RecordTime("Bond传入等待区线程异常", $"{ex.Message}");
                            AKRSXtraMessageBox.Show($"Bond传入等待区线程异常：{ex.Message}");
                        }
                    });
                this.transferBondToWaitingUnloadTask.ConfigureAwait(false);
            }

            #region 等待区到出料

            // 未配置自动上下料
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.None)
            {
                return;
            }
            else if (MachineHardwareConfiguration.GetInstance().LoadConfiguration != LoadConfigurationEnum.LoaderBin)
            {
                if (this.transferWaitingUnloadToUnloadBeltTask == null || this.transferWaitingUnloadToUnloadBeltTask.Status != TaskStatus.Running)
                {
                    this.transferWaitingUnloadToUnloadBeltTask = Task.Run(
                        () =>
                            {
                                CommonUtil.SetCurrentThreadName("等待区传入出料区线程");
                                try
                                {
                                    while (Signal.WaitStart())
                                    {
                                        ExcuteResult ret = this.transportController.TransferWaitingUnloadToUnloadBelt();

                                        switch (ret)
                                        {
                                            case ExcuteResult.NoStart:

                                                break;

                                            case ExcuteResult.Abort:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Abort");

                                                Machine.GetInstance().Stop();

                                                TransportProvider.RecordTime("等待区传入出料区线程", "设备停止");
                                                break;

                                            case ExcuteResult.Success:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Success");
                                                break;

                                            case ExcuteResult.Exception:

                                                TransportProvider.RecordTime("等待区传入出料区线程", "返回Exception");

                                                Machine.GetInstance().Stop();
                                                break;
                                        }

                                        Thread.Sleep(100);
                                    }
                                }
                                catch (Exception ex)
                                {
                                    AKRSXtraMessageBox.Show($"等待区传入出料区线程：{ex.Message}");
                                }
                            });
                    this.transferWaitingUnloadToUnloadBeltTask.ConfigureAwait(false);
                }
            }
            else   // 配置自动上下料
            {
                if (this.transferWaitingUnloadToUnloadBinTask == null || this.transferWaitingUnloadToUnloadBinTask.Status != TaskStatus.Running)
                {
                    this.transferWaitingUnloadToUnloadBinTask = Task.Run(
                        () =>
                        {
                            CommonUtil.SetCurrentThreadName("等待区传入下料仓线程");
                            bool firstStart = true;
                            try
                            {
                                // 正在工作
                                while (Signal.WaitStart())
                                {
                                    // 等允许推料信号
                                    if (!SignalPool.GetInstance().UnloaderAllowPushSignal.Wait())
                                    {
                                        return;
                                    }

                                    // 推料到下料仓
                                    ExcuteResult ret = this.transportController.TransferWaitingUnloadToUnloadBin();

                                    switch (ret)
                                    {
                                        case ExcuteResult.NoStart:
                                            Thread.Sleep(500);
                                            continue;

                                        case ExcuteResult.Abort:
                                            Machine.GetInstance().Stop();
                                            return;

                                        case ExcuteResult.Success:
                                            break;

                                        case ExcuteResult.Exception:
                                            Machine.GetInstance().Stop();
                                            return;
                                    }

                                    Thread.Sleep(200);

                                    // 手动复位
                                    SignalPool.GetInstance().UnloaderAllowPushSignal.ReSet();

                                    // 允许下料仓移动
                                    SignalPool.GetInstance().AllowUnloaderMoveSignal.Set();
                                }
                            }
                            catch (Exception ex)
                            {
                                AKRSXtraMessageBox.Show($"等待区传入下料仓线程：{ex.Message}");
                            }
                        });
                    this.transferWaitingUnloadToUnloadBinTask.ConfigureAwait(false);
                }
            }

            #endregion

            #region 出料段到收板机(联机)

            // 联机
            if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online || MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.OnlineWithAutoUnloader)
            {
                if (this.transferUnloadBeltToAutoUnloaderTask == null
                    || this.transferUnloadBeltToAutoUnloaderTask.Status != TaskStatus.Running)
                {
                    this.transferUnloadBeltToAutoUnloaderTask = Task.Run(() =>
                    {
                        CommonUtil.SetCurrentThreadName("出料段到收板机线程");

                        bool firstStart = true;
                        try
                        {
                            // 正在工作
                            while (Signal.WaitStart())
                            {
                                ExcuteResult ret = this.transportController.TransferUnloadBeltToAutoUnloader();

                                switch (ret)
                                {
                                    case ExcuteResult.NoStart:
                                        Thread.Sleep(100);
                                        break;

                                    case ExcuteResult.Abort:
                                        Machine.GetInstance().Stop();
                                        break;

                                    case ExcuteResult.Success:


                                        break;
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            AKRSXtraMessageBox.Show($"出料段到收板机线程：{ex.Message}");
                        }
                    });
                    this.transferUnloadBeltToAutoUnloaderTask.ConfigureAwait(false);
                }
            }

            #endregion
        }
